class VolumeCalculator:
    def __init__(self, shapes=[]):
        self.shapes = shapes

    def sum(self):
        total_volume = 0
        for shape in self.shapes:
            if hasattr(shape, 'volume'):
                total_volume += shape.volume()
            else:
                raise Exception("Invalid Shape: Shape does not implement volume method")
        return total_volume

